def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep=False)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df = df[df['body_mass_g'].between(2500, 6500)]
    allowed_species = ['Adelie', 'Chinstrap', 'Gentoo']
    df = df[df['species'].isin(allowed_species)]
    return df

def answer(df):
    species_sums = df.groupby('species')['body_mass_g'].sum().reset_index()
    return species_sums.set_index('species')['body_mass_g'].to_dict()
